% Individual name roles
% takes two arguments
% {<pre punct>}{<wrapper>}
\newbibmacro*{role}[2]{%
  \apabbx@ifrole@item
    {#1%
     #2{%
       \togglefalse{apabbx:role:item:punct}%
       \hasitemannotation[\currentname][role]%
         {\getitemannotation[\currentname][role]}
